/**
 * guideQrRedirectsTasklist.js
 *
 * Redirect mapping for the 20 November 2026 Ahangama Guide task-list QR batch.
 * This file is deliberately separate from `guideQrRedirects.js` and
 * `guideQrRedirectsNew.js` so the original seven QR codes and the earlier 39
 * QR codes remain completely untouched.
 *
 * Every QR code encodes a permanent URL:
 *   https://ahangama.com/go/{slug}
 *
 * Confirmed destinations point at live pages, official booking pages, official
 * Instagram profiles, or the live venue detail pages returned by the site.
 * Provisional destinations use the safe /guide fallback until the missing
 * information is supplied. They are marked `status: "provisional"` and are
 * listed in MISSING-DESTINATIONS.md.
 *
 * To change a destination, edit only `destination`. Never change `slug`,
 * `section` or `codeId` after the artwork has been printed.
 */

