/**
 * Returns the redirect config for a task-list /go/ slug, or null if not found.
 * @param {string} slug
 */
export function getTasklistQrRedirect(slug) {
  return GUIDE_QR_REDIRECTS_TASKLIST.find((entry) => entry.slug === slug) ?? null;
}
